fn main() {
    let north = vec![("bolt", 40, 3), ("hinge", 8, 25), ("plate", 15, 12)];
    let south = vec![
        ("clamp", 6, 45),
        ("rod", 22, 9),
        ("washer", 100, 1),
        ("gasket", 4, 30),
    ];
    fn process(wh: &str, parts: &[(&str, i32, i32)]) {
        let mut total = 0;
        let mut below_ten = 0;
        let mut max_value = 0;
        let mut max_part = "";
        for &(name, quantity, price) in parts {
            let value = quantity * price;
            total += value;
            if quantity < 10 {
                below_ten += 1;
            }
            if value > max_value {
                max_value = value;
                max_part = name;
            }
        }
        println!("{}", wh);
        println!("{}", total);
        println!("{}", below_ten);
        println!("{}", max_part);
    }
    process("North", &north);
    process("South", &south);
    let north_total: i32 = north.iter().map(|&(_, q, p)| q * p).sum();
    let south_total: i32 = south.iter().map(|&(_, q, p)| q * p).sum();
    if north_total > south_total {
        println!("North");
    } else {
        println!("South");
    }
}

fn main() {
    let numbers = [360, 97, 1024, 561, 143, 2003];
    let mut primes_count = 0;
    for &num in &numbers {
        println!("{}", num);
        let (divisors, sum, max) = prime_divisors(num);
        println!("{}", divisors.len());
        println!("{}", sum);
        println!("{}", max);
        if is_prime(num) {
            println!("true");
            primes_count += 1;
        } else {
            println!("false");
        }
    }
    println!("{}", primes_count);
}
fn prime_divisors(mut n: u64) -> (Vec<u64>, u64, u64) {
    let mut divisors = Vec::new();
    let mut sum = 0;
    let mut max = 0;
    while n % 2 == 0 {
        if divisors.is_empty() || divisors[divisors.len() - 1] != 2 {
            divisors.push(2);
            sum += 2;
            max = 2;
        }
        n /= 2;
    }
    let mut i = 3;
    while i * i <= n {
        while n % i == 0 {
            if divisors.is_empty() || divisors[divisors.len() - 1] != i {
                divisors.push(i);
                sum += i;
                max = i;
            }
            n /= i;
        }
        i += 2;
    }
    if n > 2 {
        divisors.push(n);
        sum += n;
        max = n;
    }
    (divisors, sum, max)
}
fn is_prime(num: u64) -> bool {
    if num <= 1 {
        return false;
    }
    for i in 2..=((num as f64).sqrt() as u64) {
        if num % i == 0 {
            return false;
        }
    }
    true
}

